import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Roo Code","description":"Connect Roo Code to Tokeness using an OpenAI Compatible provider.","frontmatter":{"title":"Roo Code","description":"Connect Roo Code to Tokeness using an OpenAI Compatible provider."},"headers":[],"relativePath":"integrations/roo-code.md","filePath":"integrations/roo-code.md","lastUpdated":1783700215000}'),i={name:"integrations/roo-code.md"};function d(n,e,l,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="roo-code" tabindex="-1">Roo Code <a class="header-anchor" href="#roo-code" aria-label="Permalink to &quot;Roo Code&quot;">​</a></h1><p>Roo Code is a coding assistant for VS Code. It supports the <code>OpenAI Compatible</code> provider, which lets you fill in a custom Base URL, API Key, and Model ID.</p><h2 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h2><p>First, prepare the following in the Tokeness console:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Model ID</td><td>Full model name copied from the Tokeness model marketplace</td></tr></tbody></table><p>Roo Code relies heavily on tool calls. For coding tasks, prefer models on Tokeness that are confirmed to support OpenAI tool calling.</p><h2 id="add-a-provider" tabindex="-1">Add a provider <a class="header-anchor" href="#add-a-provider" aria-label="Permalink to &quot;Add a provider&quot;">​</a></h2><p>Configure the following in VS Code:</p><ol><li>Open Roo Code.</li><li>Go to settings.</li><li>Find API Provider.</li><li>Select <code>OpenAI Compatible</code>.</li><li>Set Base URL to <code>https://n.tokeness.io/v1</code>.</li><li>Enter your Tokeness API key.</li><li>Enter the model name copied from the Tokeness model marketplace.</li><li>Save the configuration.</li></ol><p>Field mapping:</p><table tabindex="0"><thead><tr><th>Roo Code field</th><th>Tokeness value</th></tr></thead><tbody><tr><td>API Provider</td><td><code>OpenAI Compatible</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness API key</td></tr><tr><td>Model / Model ID</td><td>Tokeness model name</td></tr></tbody></table><h2 id="model-configuration" tabindex="-1">Model configuration <a class="header-anchor" href="#model-configuration" aria-label="Permalink to &quot;Model configuration&quot;">​</a></h2><p>If Roo Code asks for model context window or output length, start with conservative values:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Notes</th></tr></thead><tbody><tr><td>Context Window</td><td>Use the context size shown in the Tokeness model marketplace; when unsure, start with a smaller value</td></tr><tr><td>Max Output Tokens</td><td>For the first test, use 2048 or 4096</td></tr><tr><td>Image Support</td><td>Enable only if the model explicitly supports image input</td></tr><tr><td>Computer Use</td><td>Enable only if both the current model and environment support it</td></tr></tbody></table><p>Do not enable all advanced capabilities at once. Get chat and simple file edits working first, then gradually enable more complex features.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Test in the following order:</p><ol><li>Create a temporary file.</li><li>Ask Roo Code to explain a small piece of code.</li><li>Then ask it to modify the temporary file.</li><li>After each step, check the Tokeness usage logs.</li></ol><p>If there are no requests in the Tokeness logs, Roo Code is not currently using the Tokeness provider. Go back to the settings page and check whether the provider was saved successfully.</p><h2 id="tool-calling-notes" tabindex="-1">Tool calling notes <a class="header-anchor" href="#tool-calling-notes" aria-label="Permalink to &quot;Tool calling notes&quot;">​</a></h2><p>Roo Code uses the native OpenAI tool-calling format. If a model does not support tool calling, it may answer ordinary questions but cannot reliably perform tasks like reading files, editing files, or running commands.</p><p>When you encounter tool-calling issues, make two checks first:</p><ol><li>Can the same model return content through a regular Chat Completions request?</li><li>Does the model support OpenAI-compatible tool calls?</li></ol><p>If the first check passes but the second fails, switch to a model that supports tool calling — do not keep adjusting the Base URL or key.</p><h2 id="common-issues" tabindex="-1">Common issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Invalid API Key</td><td>Re-copy the key and confirm there are no line breaks, spaces, or non-ASCII quotation marks</td></tr><tr><td>Model Not Found</td><td>Re-copy the full model name from the Tokeness model marketplace</td></tr><tr><td>Connection Error</td><td>Check that the Base URL is <code>https://n.tokeness.io/v1</code></td></tr><tr><td>Chat works but file operations fail</td><td>Switch to a model that supports tool calling</td></tr><tr><td>Output interrupted</td><td>Reduce the task size, or increase Max Output Tokens</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://docs.roocode.com/providers/openai-compatible" target="_blank" rel="noreferrer">Roo Code OpenAI Compatible Provider</a></li></ul>',28)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
